const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, TabStopType, TabStopPosition,
  HeadingLevel, BorderStyle, WidthType, ShadingType, VerticalAlign,
  PageNumber, PageBreak, ExternalHyperlink
} = require("docx");

// Palette
const INK = "211C17";     // warm near-black, headings
const BODY = "2E2A25";    // body text
const ACCENT = "A8895C";  // muted gold / bronze
const SOFT = "6B645B";    // secondary / captions
const LINE = "D8CFC2";    // soft warm rule
const HEADFILL = "F2ECE2";
const ALTFILL = "FAF7F1";

const FONT = "Georgia";

// helpers
const rule = (color = ACCENT, size = 12) => new Paragraph({
  spacing: { before: 60, after: 180 },
  border: { bottom: { style: BorderStyle.SINGLE, size, color, space: 1 } },
  children: [new TextRun({ text: "", font: FONT })],
});

const body = (text, opts = {}) => new Paragraph({
  spacing: { after: opts.after === undefined ? 160 : opts.after, line: 276 },
  alignment: opts.align || AlignmentType.LEFT,
  children: [new TextRun({ text, font: FONT, size: 21, color: BODY, italics: !!opts.italics, bold: !!opts.bold })],
});

const runs = (children, opts = {}) => new Paragraph({
  spacing: { after: opts.after === undefined ? 160 : opts.after, line: 276 },
  children,
});

const bullet = (text, boldLead) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 90, line: 270 },
  children: boldLead
    ? [new TextRun({ text: boldLead, font: FONT, size: 21, color: INK, bold: true }),
       new TextRun({ text: text, font: FONT, size: 21, color: BODY })]
    : [new TextRun({ text, font: FONT, size: 21, color: BODY })],
});

const numbered = (text, boldLead) => new Paragraph({
  numbering: { reference: "steps", level: 0 },
  spacing: { after: 110, line: 270 },
  children: boldLead
    ? [new TextRun({ text: boldLead, font: FONT, size: 21, color: INK, bold: true }),
       new TextRun({ text: text, font: FONT, size: 21, color: BODY })]
    : [new TextRun({ text, font: FONT, size: 21, color: BODY })],
});

const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 320, after: 60 },
  children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: INK })],
});

const eyebrow = (text) => new Paragraph({
  spacing: { before: 40, after: 40 },
  children: [new TextRun({ text: text.toUpperCase(), font: FONT, size: 16, color: ACCENT, bold: true, characterSpacing: 40 })],
});

// table cell builder
const cell = (children, width, fill, valign = VerticalAlign.TOP) => new TableCell({
  width: { size: width, type: WidthType.DXA },
  shading: fill ? { fill, type: ShadingType.CLEAR } : undefined,
  verticalAlign: valign,
  margins: { top: 100, bottom: 100, left: 140, right: 140 },
  borders: {
    top: { style: BorderStyle.SINGLE, size: 1, color: LINE },
    bottom: { style: BorderStyle.SINGLE, size: 1, color: LINE },
    left: { style: BorderStyle.SINGLE, size: 1, color: LINE },
    right: { style: BorderStyle.SINGLE, size: 1, color: LINE },
  },
  children,
});

const cellText = (text, { bold, color, size, align } = {}) => new Paragraph({
  alignment: align || AlignmentType.LEFT,
  spacing: { after: 0, line: 264 },
  children: [new TextRun({ text, font: FONT, size: size || 19, bold: !!bold, color: color || BODY })],
});

// ---- Engagement table ----
const COLS = [2500, 4460, 2400];
const engagementTable = new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: COLS,
  rows: [
    new TableRow({
      tableHeader: true,
      children: [
        cell([cellText("Engagement", { bold: true, color: INK })], COLS[0], HEADFILL),
        cell([cellText("What it includes", { bold: true, color: INK })], COLS[1], HEADFILL),
        cell([cellText("Investment", { bold: true, color: INK, align: AlignmentType.RIGHT })], COLS[2], HEADFILL),
      ],
    }),
    new TableRow({
      children: [
        cell([cellText("Clarity Diagnostic", { bold: true, color: INK })], COLS[0], "FFFFFF"),
        cell([cellText("Confidential Experience Assessment plus Revenue Leak Audit, delivered as a written report and a live strategy session.")], COLS[1], "FFFFFF"),
        cell([cellText("$2,500", { bold: true, color: INK, align: AlignmentType.RIGHT })], COLS[2], "FFFFFF"),
      ],
    }),
    new TableRow({
      children: [
        cell([cellText("Done With You", { bold: true, color: INK }), cellText("90-day program", { color: SOFT, size: 17 })], COLS[0], ALTFILL),
        cell([cellText("Market Blueprint, Revenue Leak Audit, the full playbook library, and biweekly direction. Your team implements.")], COLS[1], ALTFILL),
        cell([cellText("$9,000", { bold: true, color: INK, align: AlignmentType.RIGHT })], COLS[2], ALTFILL),
      ],
    }),
    new TableRow({
      children: [
        cell([cellText("Done For You", { bold: true, color: INK }), cellText("90-day program", { color: SOFT, size: 17 })], COLS[0], "FFFFFF"),
        cell([cellText("Everything in Done With You, and we build it with you: biweekly calls, Slack support, the proprietary TLC AI tool, and the conversion engine installed for you.")], COLS[1], "FFFFFF"),
        cell([cellText("$15,000", { bold: true, color: INK, align: AlignmentType.RIGHT })], COLS[2], "FFFFFF"),
      ],
    }),
    new TableRow({
      children: [
        cell([cellText("One-to-One Strategic Consulting", { bold: true, color: INK })], COLS[0], ALTFILL),
        cell([cellText("Bethany Anne directly, on-site visits, and hands-on guidance built around your multi-location roadmap. Reserved for three to four clients at a time.")], COLS[1], ALTFILL),
        cell([cellText("$10,000 / month", { bold: true, color: INK, align: AlignmentType.RIGHT })], COLS[2], ALTFILL),
      ],
    }),
  ],
});

// ---- Document ----
const doc = new Document({
  creator: "The Luxora Collective",
  title: "Growth Partnership Proposal - Blue Cineal",
  styles: {
    default: { document: { run: { font: FONT, size: 21, color: BODY } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 34, bold: true, font: FONT, color: INK },
        paragraph: { spacing: { before: 240, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: INK },
        paragraph: { spacing: { before: 320, after: 60 }, outlineLevel: 1 } },
    ],
  },
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
        style: { run: { color: ACCENT }, paragraph: { indent: { left: 460, hanging: 260 } } } }] },
      { reference: "steps", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 460, hanging: 280 } } } }] },
    ],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 },
      },
    },
    footers: {
      default: new Footer({
        children: [
          new Paragraph({
            tabStops: [{ type: TabStopType.RIGHT, position: 9360 }],
            border: { top: { style: BorderStyle.SINGLE, size: 4, color: LINE, space: 6 } },
            children: [
              new TextRun({ text: "The Luxora Collective", font: FONT, size: 16, color: SOFT }),
              new TextRun({ text: "\ttheluxoracollective.co", font: FONT, size: 16, color: SOFT }),
            ],
          }),
        ],
      }),
    },
    children: [
      // ---------- COVER ----------
      new Paragraph({ spacing: { before: 1200, after: 0 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: FONT, size: 20, bold: true, color: ACCENT, characterSpacing: 80 })] }),
      rule(ACCENT, 10),
      new Paragraph({ spacing: { before: 240, after: 60 },
        children: [new TextRun({ text: "Growth Partnership Proposal", font: FONT, size: 50, bold: true, color: INK })] }),
      new Paragraph({ spacing: { after: 40 },
        children: [new TextRun({ text: "Prepared for Colleen Lewis", font: FONT, size: 26, color: BODY })] }),
      new Paragraph({ spacing: { after: 0 },
        children: [new TextRun({ text: "Founder, Blue Cineal", font: FONT, size: 22, italics: true, color: SOFT }),
                   new TextRun({ text: "   |   Scottsdale, Arizona", font: FONT, size: 22, color: SOFT })] }),

      new Paragraph({ spacing: { before: 2600, after: 40 },
        children: [new TextRun({ text: "Prepared by", font: FONT, size: 17, color: ACCENT, bold: true, characterSpacing: 40 })] }),
      new Paragraph({ spacing: { after: 20 },
        children: [new TextRun({ text: "Bethany Anne Hotchkiss", font: FONT, size: 24, bold: true, color: INK })] }),
      new Paragraph({ spacing: { after: 20 },
        children: [new TextRun({ text: "Co-Founder & CEO, The Luxora Collective", font: FONT, size: 20, color: BODY })] }),
      new Paragraph({ spacing: { after: 0 },
        children: [new TextRun({ text: "July 2026", font: FONT, size: 20, color: SOFT })] }),

      new Paragraph({ children: [new PageBreak()] }),

      // ---------- OPENING NOTE ----------
      eyebrow("A note before the details"),
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: "Colleen,", font: FONT, size: 34, bold: true, color: INK })] }),
      body("Thank you for the conversation. It is rare to finish a first call already certain that the person on the other end is building something exceptional. You are."),
      body("Blue Cineal is seven months old, already four-wall break even, and you collected $157,000 in cash in May with seventy active members and a brand your competitors are not matching. That is not a practice that needs fixing. It is a practice that is ready to accelerate."),
      body("So this proposal is written in that spirit. I am not going to suggest rebuilding systems you have already mastered. You have the standards of care, the operating procedures, the financial discipline, and the team culture handled at a level most owners never reach. What I want to offer instead is an outside lens on a small number of high-leverage gaps, and a way to convert more of the demand you are already creating, without it living on your phone."),

      // ---------- WHAT I HEARD ----------
      h2("What I heard"),
      rule(LINE, 6),
      body("A few specific opportunities stood out on our call. None of them are about effort or competence. They are about leverage and time."),
      bullet("Converting Meta leads into booked appointments is the bottleneck, and right now that work lives with you. Following up on every lead personally is not sustainable, and Annie joining in August gives you a person, not yet a system.", "Lead conversion. "),
      bullet("You have AI and automation in place, and you already sense there is far more available there. There is. The cadence, the speed-to-lead, and the brand voice can all be built out so leads are worked in minutes without you.", "The Go High Level engine. "),
      bullet("The corporate wellness deck is built. The surgeon, orthopedic, physical therapy, and breast reconstruction referral pipeline is obvious, and plastic surgeons are already reaching out. What is missing is the time to execute the outreach.", "Partnership revenue, designed but not yet activated. "),
      bullet("You have three thousand plus names and a list of clients who came once and have not returned. That is recoverable revenue sitting in your own database.", "Reactivation. "),
      bullet("Two of your providers convert above sixty percent and two sit between thirty and forty. Closing that gap is real money, and it is a coaching and scripting problem, not a talent problem.", "Consultation and rebooking conversion. "),
      bullet("The member versus a la carte spend figure you have been meaning to pull is one example of a wider point: before you scale to multiple markets, a clean KPI picture is worth building once and reusing everywhere.", "The numbers, before you scale. "),

      // ---------- WHERE LUXORA FITS ----------
      h2("Where Luxora fits"),
      rule(LINE, 6),
      body("We are not a marketing agency, a consultancy, or a coaching program. We are a growth partner. We work inside out: clarity first, then targeted acceleration on the specific gaps, then expansion support as you open locations two and three. For you, that maps cleanly onto what we discussed."),

      runs([new TextRun({ text: "Speed-to-lead conversion engine. ", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: "We build the follow-up automation inside Go High Level with brand-aligned scripting and assisted booking, so leads are engaged in minutes and arrive on the calendar already warm. Annie steps into a system instead of a fire, and you step out of the loop.", font: FONT, size: 21, color: BODY })]),
      runs([new TextRun({ text: "Confidential Experience Assessment. ", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: "The secret shopper you lit up about. I move through your funnel as a client, from speed-to-lead through the front desk, the consultation, the rebooking, and the room itself, then deliver a written report and a strategy session. For a brand built on experience, this is gold, and it becomes a repeatable quality tool as you open each new location.", font: FONT, size: 21, color: BODY })]),
      runs([new TextRun({ text: "Revenue Leak Audit and KPI clarity. ", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: "We surface the small things that add up, including the member versus a la carte spend data and the provider conversion gap, and hand you a KPI picture you can carry into every future market.", font: FONT, size: 21, color: BODY })]),
      runs([new TextRun({ text: "Partnership and collaboration arm. ", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: "Our outreach function executes the corporate wellness program and the surgeon referral pipeline you have already designed. This is upside revenue you are leaving on the table only for lack of bandwidth.", font: FONT, size: 21, color: BODY })]),
      runs([new TextRun({ text: "Reactivation. ", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: "Campaigns against your existing database and the one-time, never-returned list you already pulled. This is typically the fastest revenue in the engagement.", font: FONT, size: 21, color: BODY })]),
      runs([new TextRun({ text: "Market Blueprint. ", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: "Positioning and ad strategy for Scottsdale now, and the same diligence as a repeatable tool for Denver, Texas, and yes, Brentwood. As you scale, this is where our value compounds.", font: FONT, size: 21, color: BODY })]),
      body("One note on wellness: your integration of aesthetics and longevity is already best in class. We would support and amplify it, never rebuild it.", { after: 40 }),

      new Paragraph({ children: [new PageBreak()] }),

      // ---------- RECOMMENDED PATH ----------
      h2("A recommended path"),
      rule(LINE, 6),
      body("Given where you are, the honest recommendation is not a big commitment up front. It is a precise first step that proves value, followed by the option to accelerate."),
      numbered("Start here. The Confidential Experience Assessment paired with the Revenue Leak Audit. Low commitment, high signal, and a direct answer to your question about running the audit on its own. You will leave with a written report and a clear picture of where the leverage is.", "Phase one: Clarity Diagnostic. "),
      numbered("Based on what the diagnostic surfaces, move into the Done For You program for a defined ninety-day sprint with a revenue guarantee, or into ongoing One-to-One Strategic Consulting if the priority is the multi-location roadmap. We decide together, with data in hand.", "Phase two: Acceleration. "),

      // ---------- ENGAGEMENT OPTIONS ----------
      h2("Engagement options"),
      rule(LINE, 6),
      body("Every tier includes the Revenue Leak Audit and the playbook library relevant to your goals. You can start small and scale up at any point.", { after: 200 }),
      engagementTable,
      new Paragraph({ spacing: { after: 120 }, children: [new TextRun({ text: "", font: FONT })] }),

      runs([new TextRun({ text: "If your team has the bandwidth to implement, ", font: FONT, size: 21, color: BODY }),
            new TextRun({ text: "Done With You", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: " gives you the full strategy and playbooks to run internally. If the bottleneck is time, which is what I heard, ", font: FONT, size: 21, color: BODY }),
            new TextRun({ text: "Done For You", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: " is the better fit: we build the conversion engine, run the partnership outreach, and stay connected by biweekly call and Slack, with the TLC AI tool available to you and your team around the clock. For the multi-location vision specifically, ", font: FONT, size: 21, color: BODY }),
            new TextRun({ text: "One-to-One Strategic Consulting", font: FONT, size: 21, bold: true, color: INK }),
            new TextRun({ text: " puts me on-site and in the work with you as you expand.", font: FONT, size: 21, color: BODY })]),

      // ---------- GUARANTEE ----------
      h2("The guarantee"),
      rule(LINE, 6),
      new Paragraph({
        shading: { fill: ALTFILL, type: ShadingType.CLEAR },
        border: { left: { style: BorderStyle.SINGLE, size: 18, color: ACCENT, space: 12 } },
        spacing: { before: 60, after: 60, line: 288 },
        indent: { left: 200, right: 200 },
        children: [
          new TextRun({ text: "On the Done For You program, our work carries a simple commitment: you will see at least two times your investment in new and recovered revenue within ninety days, or we keep working at no additional cost until you do.", font: FONT, size: 22, italics: true, color: INK }),
        ],
      }),

      // ---------- WHY LUXORA ----------
      h2("Why Luxora"),
      rule(LINE, 6),
      bullet("Aesthetics and wellness are all we do. You have already fired generalist agencies that produced off-brand assets and aggressive bookers. We will never put a used-car-salesman voice in front of your clients.", "Specialists, not generalists. "),
      bullet("I spent my career inside this industry, including operating a derm and plastics group to seven million in revenue. My co-founder Eric builds, scales, and exits companies, and he is in Scottsdale half the year, so your market is not abstract to us.", "Built by operators. "),
      bullet("As you move toward fifteen to twenty locations, we can open warm connections across the industry, including the expansion and acquisition partners we already work with.", "A network for your roadmap. "),

      // ---------- NEXT STEPS ----------
      h2("Next steps"),
      rule(LINE, 6),
      numbered("Review this with Brett at your pace. After the fourth is perfect, and enjoy Maine.", "Review. "),
      numbered("A short call to choose a starting point. My recommendation is the Clarity Diagnostic, so your decision on phase two is made with real findings rather than guesses.", "Choose. "),
      numbered("We schedule the assessment and the work begins.", "Begin. "),

      new Paragraph({ spacing: { before: 260, after: 160 }, children: [new TextRun({ text: "Whatever you decide, I meant what I said on the call. I want Blue Cineal to win, and if the right move is for us to lock arms, I would be honored to do it.", font: FONT, size: 21, italics: true, color: BODY })] }),

      new Paragraph({ spacing: { before: 120, after: 20 }, children: [new TextRun({ text: "Warmly,", font: FONT, size: 21, color: BODY })] }),
      new Paragraph({ spacing: { after: 0 }, children: [new TextRun({ text: "Bethany Anne Hotchkiss", font: FONT, size: 22, bold: true, color: INK })] }),
      new Paragraph({ spacing: { after: 0 }, children: [new TextRun({ text: "Co-Founder & CEO, The Luxora Collective", font: FONT, size: 19, color: SOFT })] }),
      new Paragraph({ spacing: { after: 0 }, children: [
        new ExternalHyperlink({ link: "https://theluxoracollective.co", children: [new TextRun({ text: "theluxoracollective.co", font: FONT, size: 19, color: ACCENT })] }),
      ] }),
    ],
  }],
});

Packer.toBuffer(doc).then((buffer) => {
  fs.writeFileSync("/mnt/user-data/outputs/Blue_Cineal_Growth_Proposal.docx", buffer);
  console.log("written");
});

